def distinctSubsequences(S):
    dp = [set() for _ in range(len(S))]
    dp[0].add(S[0])
    for i in range(1, len(S)):
        dp[i].add(S[i])
        for j in range(i):
            for sub in dp[j]:
                dp[i].add(sub + S[i])
    return len(dp[-1])
```
